-- Location functions: French in base columns, English in translations.en (task 1a2205a7).
-- Text approved by Luigi 2026-10-15 (doc « Textes FR à valider, pages en anglais »).
-- Apply ONLY after the code change that localizes function label/description is merged
-- (task 1a2205a7, brief in docs/briefs/2026-10-15-night.md), else /en shows French.
-- claude.ai applies, one statement per call. Verify with v_translation_health afterwards.

with v(id, fl, fd, el, ed) as (values
  ('95e5e010-283e-4910-b531-0a9a14fb73c9'::uuid, $$Musée de l'École de Barbizon$$, $$Musée départemental depuis 2004, ouvert en 1995 dans l'ancienne auberge. Murs peints par les artistes, mobilier et objets de l'époque de l'auberge, collection permanente consacrée à l'école de Barbizon (1830-1870).$$, $$Musée de l'École de Barbizon$$, $$Departmental museum since 2004, opened in 1995 in the former inn. Walls painted by the artists, furniture and objects from the inn years, and a permanent collection devoted to the Barbizon School (1830–1870).$$),
  ('7e1ed0c8-ae5c-42a1-9f52-7c98fa7f16b5'::uuid, $$Galerie d'art contemporain$$, $$Collection internationale, avec notamment Mauro Corda, Jean-François Larrieu, Eishin Yoza et Antoni Taulé. Deux jardins de sculptures. Collection permanente et expositions temporaires toute l'année.$$, $$Contemporary art gallery$$, $$International collection including Mauro Corda, Jean-François Larrieu, Eishin Yoza, and Antoni Taulé. Two sculpture gardens. Permanent collection and temporary exhibitions year-round.$$),
  ('ad7e6957-586d-4e63-9afe-2980116eed04'::uuid, $$Suites d'art$$, $$Des chambres au cœur de la collection : chaque suite est entourée d'œuvres de la collection permanente. Les jardins de sculptures sont accessibles aux résidents.$$, $$Art suites$$, $$Rooms within the gallery collection. Each suite is surrounded by works from the permanent collection. Sculpture gardens accessible to residents.$$),
  ('bf05e76c-198d-43f3-85fb-fe928b359aeb'::uuid, $$Hôtel 4 étoiles et restaurant$$, $$Hôtel historique dans un parc ombragé de 2 hectares, en lisière de la forêt de Fontainebleau. Restaurant, terrasse et accès direct à la forêt.$$, $$4-star hotel and restaurant$$, $$Historic hotel in a shaded 2-hectare park at the edge of the Fontainebleau forest. Restaurant, terrace, and direct forest access.$$),
  ('6d848b17-e4b4-456d-8f6c-298fa46a22a4'::uuid, $$Restaurant gastronomique$$, $$Carte de saison signée Cyrine Jarretie : produits frais, technique classique, assiettes généreuses. Distingué par le Gault & Millau. Terrasse et véranda vitrée. Déjeuner de 12 h à 14 h 30, dîner de 19 h 30 à minuit, du jeudi au lundi. Réservation conseillée.$$, $$Fine dining restaurant$$, $$Seasonal French menu by Cyrine Jarretie. Fresh produce, classical technique, generous portions. Gault & Millau noted. Terrace and glazed verandah. Lunch 12:00–14:30, dinner 19:30–midnight, Thursday to Monday. Reservations recommended.$$),
  ('24ff41df-ee6f-47b9-85fa-c22461a0e3df'::uuid, $$Bar à tapas, happy hour, brunch$$, $$L'offre décontractée de la journée et du début de soirée : planches de tapas, happy hour, brunch le week-end. Une alternative légère à la carte gastronomique, sans réservation.$$, $$Tapas bar, happy hour, brunch$$, $$Informal daytime and early-evening offer: tapas boards, happy hour drinks, weekend brunch. A lighter alternative to the full gastronomic menu, open to walk-ins.$$),
  ('ca59bbde-d857-4da4-b699-ac5b380f1fa5'::uuid, $$Coffee shop$$, $$Le café du matin, dès 10 h : café, viennoiseries et petite restauration. La façon la plus simple d'entrer dans la maison, sans réservation.$$, $$Coffee shop$$, $$Morning café open from 10:00. Coffee, pastries and light bites. The easiest way into the house, no reservation needed.$$),
  ('270ec9b7-ba7b-4d57-845a-7d79cd23d8a5'::uuid, $$L'Autre Nuit, bar$$, $$Bar de nuit au sous-sol, la dernière adresse ouverte du village : il prend le relais à la fin du service du dîner. Cocktails et vins jusqu'à minuit.$$, $$L'Autre Nuit, bar$$, $$Night bar in the basement, the latest address in the village, open after dinner service ends upstairs. Cocktails and wine until midnight.$$),
  ('1c59a983-2d2a-4c2d-909f-ed197f73a06b'::uuid, $$La Boutique par Cyrine Jarretie$$, $$Épicerie fine attenante au restaurant : vins, produits locaux et plats préparés. Ouverte tous les jours de 10 h à 21 h, y compris les jours de fermeture du restaurant. Tél. 01 64 71 00 26.$$, $$La Boutique par Cyrine Jarretie$$, $$Épicerie fine attached to the restaurant. Wine, local provisions and prepared goods. Open daily 10:00–21:00, including days when the restaurant is closed. Tel: 01 64 71 00 26.$$),
  ('47c65931-ffcf-43b5-9435-1c17022f633a'::uuid, $$Salon de thé, boutique et galerie$$, $$Distingué par le Gault & Millau. Pâtisseries maison, vingt variétés de thé et des expositions renouvelées. Une salle chaleureuse et une terrasse.$$, $$Tea room, shop and gallery$$, $$Gault & Millau noted. Handmade pastries, 20 varieties of tea, rotating gallery exhibitions. A cosy room with a terrace.$$),
  ('1653639b-dd5f-481a-9e57-10521296c37a'::uuid, $$Hôtel et bar$$, $$Neuf chambres et suites, chacune pensée autour d'un peintre impressionniste européen et de son pays (un Norvégien, un Hongrois, un Écossais) dont l'œuvre a été marquée par un séjour à Barbizon ou à Fontainebleau. Matériaux biosourcés, pas de climatisation, chambres avec accès privatif au jardin. Bar-salon ouvert aux clients comme aux visiteurs. Petit-déjeuner en chambre, au café ou en terrasse.$$, $$Hotel and bar$$, $$Nine rooms and suites, each designed around a specific European Impressionist artist and their country (a Norwegian, a Hungarian, a Scot) whose work was shaped by time in Barbizon or Fontainebleau. Bio-sourced materials, no air conditioning, rooms with private garden access. Bar lounge open to guests and visitors. Breakfast in room, at the café, or on the terrace.$$),
  ('4aafd863-2de3-4740-8b2f-9b6f5195ed3e'::uuid, $$Musée de l'Esquisse$$, $$Un musée consacré à l'histoire européenne des colonies d'artistes et au rayonnement de l'école de Barbizon hors de France. Collection permanente prêtée par des institutions européennes, dont le Museum Domburg (Pays-Bas), sous le commissariat de Francisca van Vloten. Une exposition temporaire tous les quatre mois, consacrée chaque fois à un pays et à sa colonie d'artistes. Ouvert tous les jours de 11 h à 18 h. Entrée libre.$$, $$Musée de l'Esquisse$$, $$A museum tracing the European history of artist colonies and the influence of the Barbizon School beyond France. Permanent collection on loan from institutions across Europe, including Museum Domburg (Netherlands), curated by Francisca van Vloten. Temporary exhibitions every four months, each dedicated to a specific country and colony. Open daily 11:00–18:00. Free admission.$$),
  ('dfbef7da-dfc6-42dd-8383-dec99de90fee'::uuid, $$Musée Millet$$, $$Musée privé ouvert au public depuis 1923. L'atelier, la salle à manger et la cuisine. Objets personnels, dessins, études préparatoires et un autoportrait. Ouvert tous les jours sauf le mardi d'avril à octobre, et sauf le mardi et le mercredi de novembre à mars. Entrée 5 €, enfants 4 €.$$, $$Musée Millet$$, $$Private museum open to the public since 1923. The atelier, dining room and kitchen. Personal objects, drawings, preparatory studies, and a self-portrait. Open daily except Tuesday from April to October, and except Tuesday and Wednesday from November to March. Admission €5, children €4.$$),
  ('ea359c17-f726-462c-aacb-6185d468f095'::uuid, $$Fromagerie$$, null, $$Cheese shop$$, null),
  ('4f25eac0-740e-4e99-a921-3b55bc589bb0'::uuid, $$Restaurant$$, null, $$Restaurant$$, null)
)
update location_functions lf set label = v.fl, description = v.fd,
  translations = coalesce(lf.translations, '{}'::jsonb) || jsonb_build_object('en',
    jsonb_strip_nulls(jsonb_build_object('label', v.el, 'description', v.ed)) ||
    jsonb_build_object('_meta', jsonb_build_object('source_hash', md5(coalesce(v.fl,'') || '|' || coalesce(v.fd,'')), 'translated_at', now(), 'status', 'published')))
from v where lf.id = v.id
returning lf.id
